<?php $page_title='Settings → Integrations';require_once __DIR__.'/includes/header.php';if(is_post()){verify_csrf();$action=$_POST['action']??'save';if($action==='save_whatsapp'){foreach(['whatsapp_access_token','whatsapp_phone_number_id','whatsapp_business_account_id','whatsapp_verify_token','whatsapp_test_number'] as $k)set_setting($k,$_POST[$k]??'','integrations');flash('success','WhatsApp settings saved.');}elseif($action==='save_telegram'){foreach(['telegram_bot_token','telegram_webhook_url','telegram_webhook_secret'] as $k)set_setting($k,$_POST[$k]??'','integrations');flash('success','Telegram settings saved.');}elseif($action==='save_notifications'){set_setting('notifications_whatsapp_enabled',isset($_POST['notifications_whatsapp_enabled'])?'1':'0','notifications');set_setting('notifications_telegram_enabled',isset($_POST['notifications_telegram_enabled'])?'1':'0','notifications');set_setting('notifications_email_enabled',isset($_POST['notifications_email_enabled'])?'1':'0','notifications');flash('success','Notifications saved.');}elseif($action==='set_webhook'){[$ok,$msg]=set_telegram_webhook();flash($ok?'success':'danger',$msg);}elseif($action==='test_bot'){[$ok,$msg]=test_telegram_bot();flash($ok?'success':'danger',$msg);}elseif($action==='clear_logs'){query('DELETE FROM telegram_logs');query('DELETE FROM whatsapp_logs');flash('success','Logs cleared.');}redirect('integrations.php');}$wa=setting('whatsapp_api_status','disconnected');$tg=setting('telegram_api_status','disconnected');?><div class="row"><div class="col-md-8"><div class="card mb-4"><div class="card-body"><h4>WhatsApp Cloud API</h4><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save_whatsapp"><label class="form-label">Access Token</label><textarea class="form-control mb-3" name="whatsapp_access_token" rows="3"><?=e(setting('whatsapp_access_token'))?></textarea><div class="row"><div class="col-md-6"><label class="form-label">Phone Number ID</label><input class="form-control mb-3" name="whatsapp_phone_number_id" value="<?=e(setting('whatsapp_phone_number_id'))?>"></div><div class="col-md-6"><label class="form-label">Business Account ID</label><input class="form-control mb-3" name="whatsapp_business_account_id" value="<?=e(setting('whatsapp_business_account_id'))?>"></div><div class="col-md-6"><label class="form-label">Verify Token</label><input class="form-control mb-3" name="whatsapp_verify_token" value="<?=e(setting('whatsapp_verify_token'))?>"></div><div class="col-md-6"><label class="form-label">Test Number</label><input class="form-control mb-3" name="whatsapp_test_number" value="<?=e(setting('whatsapp_test_number'))?>"></div></div><button class="btn btn-secondary">Save</button> <button class="btn btn-primary" formaction="whatsapp-send.php" name="action" value="test">Send Test Message</button></form></div></div><div class="card mb-4"><div class="card-body"><h4>Telegram Bot</h4><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save_telegram"><label class="form-label">Bot Token</label><input class="form-control mb-3" name="telegram_bot_token" value="<?=e(setting('telegram_bot_token'))?>"><label class="form-label">Webhook URL</label><input class="form-control mb-3" name="telegram_webhook_url" value="<?=e(setting('telegram_webhook_url'))?>"><label class="form-label">Webhook Secret</label><input class="form-control mb-3" name="telegram_webhook_secret" value="<?=e(setting('telegram_webhook_secret'))?>"><button class="btn btn-secondary">Save</button> <button class="btn btn-primary" name="action" value="set_webhook">Set Webhook</button> <button class="btn btn-secondary" name="action" value="test_bot">Test Bot</button></form><p class="mt-3">Connection Status: <?=status_badge($tg)?></p></div></div><div class="card"><div class="card-body"><h4>Notifications</h4><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save_notifications"><label><input type="checkbox" name="notificati